-- Fazenda Pontal: bancada do controle pelo MED-EQTL (18/11/2026). TESTE em unidade REAL: zerar depois (ver fim).
--  1) INV-01 e INV-02 (estavam fora da tela, x=-78/-75) entram no grupo A: posição antes do INV-03 e ligados em cadeia.
--  2) Projeto IoT "Controle FP - Bancada": TON-MED (ton4v2 + SSU no MED-EQTL), TON-UFV-A (INV-01..10, end. 1..10),
--     TON-UFV-B (INV-11..19, end. 1..9), todos Sungrow SG110CX, WiFi da bancada. Depois: abrir a Topologia IoT e SALVAR
--     (o backend cria as 3 TONs, os equipamentos e os vínculos). Idempotente.
BEGIN;

UPDATE equipamentos SET posicao_x = -42, posicao_y = -22, updated_at = now()
WHERE unidade_id = 'cmuhbmzan17mbjq7o8154c6vt' AND nome = 'INV-01' AND deleted_at IS NULL;
UPDATE equipamentos SET posicao_x = -39, posicao_y = -22, updated_at = now()
WHERE unidade_id = 'cmuhbmzan17mbjq7o8154c6vt' AND nome = 'INV-02' AND deleted_at IS NULL;

INSERT INTO equipamentos_conexoes (id, diagrama_id, equipamento_origem_id, porta_origem, equipamento_destino_id, porta_destino, origem_tipo, destino_tipo, created_at, updated_at)
SELECT substr(md5(random()::text || clock_timestamp()::text || a.id), 1, 26), a.diagrama_id, a.id, 'right', b.id, 'left', 'equipamento', 'equipamento', now(), now()
FROM (VALUES ('INV-01','INV-02'), ('INV-02','INV-03')) v(o, d)
JOIN equipamentos a ON a.unidade_id = 'cmuhbmzan17mbjq7o8154c6vt' AND a.nome = v.o AND a.deleted_at IS NULL
JOIN equipamentos b ON b.unidade_id = 'cmuhbmzan17mbjq7o8154c6vt' AND b.nome = v.d AND b.deleted_at IS NULL
WHERE NOT EXISTS (SELECT 1 FROM equipamentos_conexoes c WHERE c.deleted_at IS NULL
  AND ((c.equipamento_origem_id = a.id AND c.equipamento_destino_id = b.id) OR (c.equipamento_origem_id = b.id AND c.equipamento_destino_id = a.id)));

